import {activeDraw,handView,moveHandTile,sortHand,syncHandOrder,setHandAutoSort} from './hand-layout.js';
import {newGame,act,optionsFor,scoring,practice,assertState,CATALOG,price,eligible,BOSSES,CHAPTERS,meldCount,riichiAction,riichiDelay,rerollCost,sellValue,bossFor,roundTarget,ROUND_TARGETS,floorCapacity,consumableCapacity,consumableCount,migrateGame,remainingWaits} from './game.js';
import {tileName,nextDora,YAKU_HELP,domains,waits} from './rules.js';
import {actionChoices} from './controls.js';
import {KIND_NAMES,itemById,RECIPE_TAGS,SHOP_CATALOG,FOCUS_YAKU} from './catalog.js';
import {faceMarkup} from './tile-art.js';
const app=document.getElementById('app'),KEY='night-table-v25-progress-1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s,campaign=null,selected=null,floorSelected=null,selectedTool='wind',cached=null,sound=false,audio,autoTimer=null,autoPaused=false,actionMenu=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));if([25,26,27].includes(saved?.version)){if(saved.version<27&&!localStorage.getItem(KEY+'-before-v27'))localStorage.setItem(KEY+'-before-v27',JSON.stringify(saved));migrateGame(saved);assertState(saved);s=saved;}}catch{}
s??=newGame({seed:crypto.randomUUID().slice(0,8)});
const SORT_KEY='night-table-hand-auto-sort';
let autoSortHand=false;try{autoSortHand=localStorage.getItem(SORT_KEY)==='on';}catch{}
function save(){if(!s.practice)try{localStorage.setItem(KEY,JSON.stringify(s));}catch{}}
function beep(kind){if(!sound)return;try{audio??=new AudioContext();audio.resume();const now=audio.currentTime;const notes=kind==='win'?[330,440,660]:kind==='riichi'?[160,95]:[290];for(let i=0;i<notes.length;i++){const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=notes[i];g.gain.setValueAtTime(.0001,now+i*.08);g.gain.linearRampToValueAtTime(.04,now+i*.08+.01);g.gain.exponentialRampToValueAtTime(.0001,now+i*.08+.22);o.connect(g);g.connect(audio.destination);o.start(now+i*.08);o.stop(now+i*.08+.25);}}catch{}}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4200);}
function options(){return cached??=optionsFor(s);}
function chooseDefaults(){if(!s.hand.some(x=>x.id===selected))selected=s.hand.find(x=>x.id===s.drawn)?.id||s.hand[0]?.id;if(!s.floor.some(x=>x.id===floorSelected))floorSelected=null;if(!s.tools[selectedTool])selectedTool=Object.keys(s.tools)[0];}
function tile(x,area='static',extra=''){
 const t=x.resolvedAs??x.lockedAs??(x.special==='wind'?27:x.special==='dragon'?31:x.type),tag=x.special==='wind'?'東南西北':x.special==='triad'?'萬 通 索':x.special==='dual'?'萬 + 索':x.special==='dragon'?'白發中':['mirror','neighbor','adjacent'].includes(x.special)?domains(x).map(t=>t%9+1).join(' / '):x.special?'調':'';
 const content=`${faceMarkup(t)}<span class="tile-label">${t<27?`${t%9+1}${['m','p','s'][Math.floor(t/9)]}`:''}</span>${tag?`<span class="tile-tag">${tag}</span>`:''}${x.floorEffects?.length?`<span class="effect-count">✦${x.floorEffects.length}</span>`:''}`;
 const cl=`tile t${t} ${x.red?'red':''} ${x.special||x.floorEffects?.length?'special':''} ${extra} ${area==='hand'&&x.id===selected||area==='floor'&&x.id===floorSelected?'selected':''} ${area==='hand'&&x.id===activeDraw(s)?'drawn':''}`;
 const label=`${tileName(t)}${tag?` · ${tag}`:''}${x.red?' · 적도라':''}${x.floorEffects?.length?' · '+effectText(x):''}`;
 return area==='static'?`<span class="${cl}" aria-label="${esc(label)}" title="${esc(label)}">${content}</span>`:`<button type="button" draggable="${area==='hand'&&!s.riichi&&!s.autoSortHand}" class="${cl}" data-${area}="${esc(x.id)}" aria-label="${area==='hand'?'손패':'바닥패'} ${esc(label)}" aria-pressed="${area==='hand'?x.id===selected:x.id===floorSelected}">${content}</button>`;
}
const names={chi:'치',pon:'퐁',daiminkan:'대명깡',ankan:'암깡',kakan:'가깡'};
function doraPanel(){return `<div class="panel dora-panel"><div class="row spread"><h3>도라 표시패 <span class="muted">· 라운드 공유</span></h3><span class="muted">삼원패 白 · 發 · 中</span></div><div class="indicator-context"><div class="wind-summary" aria-label="장풍과 자풍"><div class="wind-item" role="group" aria-label="장풍패 동"><small>장풍</small>${tile({type:27})}<small>동</small></div><div class="wind-item" role="group" aria-label="자풍패 동"><small>자풍</small>${tile({type:27})}<small>동</small></div></div><div class="dora-row">${s.indicators.map((x,i)=>`<div class="dora-pair">${tile(x)}<small>도라 ${tileName(nextDora(x.type))}</small>${i<(s.uraKnown||0)?tile(s.ura[i]):'<span class="tile back" aria-label="비공개 뒷도라">裏</span>'}<small>${i<(s.uraKnown||0)?`뒤 ${tileName(nextDora(s.ura[i].type))}`:'뒷도라 비공개'}</small></div>`).join('')}</div></div><p class="muted" style="margin-top:8px">깡으로 늘어난 표시패와 공개한 뒷도라는 다음 손에도 유지됩니다.</p></div>`;}

function effectText(t){const counts={};for(const id of t.floorEffects||[])counts[id]=(counts[id]||0)+1;return Object.entries(counts).map(([id,n])=>`${RECIPE_TAGS[id]||'이전 도안'} ×${n}`).join(' · ');}
function floorEffectMarks(t){
 const ids=[...new Set(t.floorEffects||[])],marks=[];
 if(t.special){
  const name={triad:'삼색',adjacent:'이웃',dragon:'삼원',wind:'사풍',dual:'겹무늬',mirror:'거울',neighbor:'옆 숫자'}[t.special]||'변환';
  const symbol=['adjacent','neighbor','mirror'].includes(t.special)?'↔':t.special==='dragon'?'白':t.special==='wind'?'東':'≋';
  marks.push(`<span class="floor-mark property"><b><span aria-hidden="true">${symbol}</span> ${name}</b></span>`);
 }
 const utilities={patternSleeve:['⇄','소매'],patternHidden:['◈','은밀'],patternRefill:['↻','보충']};
 for(const id of ids){const u=utilities[id];if(u)marks.push(`<span class="floor-mark utility mark-${id}"><b><span aria-hidden="true">${u[0]}</span> ${u[1]}</b></span>`);else if(!itemById(id)?.special)marks.push(`<span class="floor-mark property"><b>${esc(RECIPE_TAGS[id]||'이전 도안')}</b></span>`);}
 return marks.length?`<div class="floor-marks" aria-label="이 패의 효과">${marks.join('')}</div>`:'<small class="plain-floor">일반패</small>';
}
function gearPanel(){return `<div class="panel"><div class="row spread"><h3>규칙·득점 장비 · ${s.equipment.length}/5</h3><span class="muted">${s.coins}냥</span></div><div class="equipment-row">${s.equipment.map(id=>`<div class="gear" title="${esc(itemById(id).text)}"><strong>${itemById(id).name}</strong><small>${id==='focus'&&s.focus?.target?`목표 ${s.focus.target} · 기본점 +${s.focus.bonus}`:itemById(id)?.text||'지난 버전의 효과'}</small></div>`).join('')||'<span class="muted">상점에서 구매 · 규칙과 점수 효과가 같은 5칸을 사용합니다.</span>'}</div></div>`;}
function recipePanel(){const total=Object.values(s.recipes).reduce((n,v)=>n+v,0);return `<div class="recipe-strip"><strong>바닥패 도안 ${total}장 <small>· 다음 새 바닥패에 자동 적용</small></strong><div class="chips">${Object.entries(s.recipes).map(([id,n])=>`<span class="chip" title="${esc(itemById(id).text)}">${RECIPE_TAGS[id]||'이전 도안'} ×${n}</span>`).join('')||'<span class="muted">아직 도안이 없습니다. 첫 라운드 후 상점에서 1냥에 구매하세요.</span>'}</div></div>`;}
function toolPanel(){const item=itemById(selectedTool),allowed=!s.riichi&&['action','floor'].includes(s.phase);return `<section class="panel consumable-panel"><div class="row spread"><h3>일회용 소모품 · ${consumableCount(s)}/${consumableCapacity(s)}</h3><span class="muted">원하는 손패·바닥패에 사용 · 라운드가 바뀌어도 재충전하지 않음</span></div><div class="tools">${Object.entries(s.tools).map(([id,t])=>`<button class="tool ${selectedTool===id?'active':''}" data-tool="${id}" aria-pressed="${selectedTool===id}"><strong>${itemById(id).name} ×${t.left}</strong></button>`).join('')||'<span class="muted">상점에서 구매한 소모품을 보관합니다.</span>'}</div>${item?`<div class="tool-info">${item.text}</div><div class="row"><button data-tool-use="hand" ${!allowed||!selected?'disabled':''}>선택 손패에 사용</button><button data-tool-use="floor" ${!allowed||!floorSelected?'disabled':''}>선택 바닥패에 사용</button></div>`:''}</section>`;}
function floorPanel(){const picked=s.floor.find(t=>t.id===floorSelected);return `<div class="floor"><div class="row spread"><h3>바닥패 진열대 · ${s.floor.length}/${s.floorSlots||floorCapacity(s)}장</h3><span class="muted">${s.blockedFloor?`총 ${s.floorSlots}칸 중 보스가 1칸 차단 · 사용 가능 ${s.floorSlots-1}칸`:'화료하면 새 바닥패를 배치합니다'}</span></div><div class="floor-tiles" style="--floor-columns:${s.floorSlots||floorCapacity(s)}">${Array.from({length:s.floorSlots||floorCapacity(s)},(_,i)=>{const t=s.floor.find(x=>x.floorSlot===i);return t?`<div class="floor-slot ${t.special?'has-property':''} ${t.floorEffects?.some(id=>['patternSleeve','patternHidden','patternRefill'].includes(id))?'has-utility':''}">${tile(t,s.riichi?'static':'floor','floor-face')}${floorEffectMarks(t)}</div>`:`<div class="floor-slot empty-slot"><span>${s.blockedFloor?.floorSlot===i?'보스 봉쇄':'빈칸'}</span><small>${s.blockedFloor?.floorSlot===i?'좁은 창 · 1칸 차단':'다음 화료 후 보충'}</small></div>`;}).join('')}</div><p class="floor-help">${s.riichi?'리치 중에는 진열대가 잠깁니다. 쯔모 화료만 가능합니다.':s.phase==='awaitDraw'?'먼저 쯔모 버튼으로 패 한 장을 뽑으세요.':s.phase==='floor'?'바닥패 선택 → 론·울기·소매 교환 / 선택하지 않고 다음 쯔모':'버린 뒤 론·울기를 선택할 수 있습니다. 소모품은 지금도 사용 가능합니다.'}</p>${picked?`<div class="selected-effects"><strong>${tileName(picked.type)} · ${effectText(picked)||'강화 없음'}</strong>${[...new Set(picked.floorEffects||[])].map(id=>`<small>${itemById(id)?.text||'지난 버전의 효과'}</small>`).join('')}</div>`:''}${picked?.floorEffects?.includes('patternSleeve')&&s.phase==='floor'&&!s.riichi?'<p class="muted">교환할 손패를 선택한 뒤 행동 메뉴에서 소매 교환을 선택하세요.</p>':''}${s.recipeTriggers?.some(x=>!x.applied)?`<p class="muted">이번 배치: 대상이 없어 미발동한 도안 ${s.recipeTriggers.filter(x=>!x.applied).length}장. 다음 배치에서 다시 시도합니다.</p>`:''}</div>`;}
function chasePanel(chase=s.riichiRun,done=false){
 if(!chase)return '';
 const consumed=done?chase.consumed:chase.startWall-s.wall.length,draws=done?chase.draws:s.riichiDraws;
 const skipped=chase.events.filter(x=>['floor','blockedFloor'].includes(x.kind)).flatMap(x=>x.tiles),misses=chase.events.filter(x=>x.kind==='tsumogiri').flatMap(x=>x.tiles);
 return `<section class="chase ${done?'finished':''}"><div class="row spread"><strong>${done?'리치 추적 결과':'리치 · 자동 추적'}</strong><span class="chase-count">패산 ${consumed}장 소모</span></div><div class="muted">선언 직전 ${chase.startWall}장 → ${chase.startWall-consumed}장 · 쯔모 ${draws}회 · ${done?'종료':`${(1050/riichiDelay(s)).toFixed(1)}× 속도`}</div><div class="chase-lane"><span>쯔모기리 ${misses.length}</span><div>${misses.slice(-10).map(x=>tile(x)).join('')||'<small>대기 중</small>'}</div></div><p class="muted">바닥패는 유지되고 쯔모패만 소모합니다.</p>${done?`<div class="chase-lane"><span>화료 판정에 사용</span><div>${chase.events.filter(x=>['winningFloor','winningDraw'].includes(x.kind)).flatMap(x=>x.tiles).map(x=>tile(x)).join('')}</div></div>`:''}${done?'':`<div class="row spread"><small>패 공개 간격이 점점 짧아집니다. 화료하면 자동으로 멈춥니다.</small><button data-pause="1">${autoPaused?'자동 진행 재개':'일시정지'}</button></div>`}</section>`;
}
function actionDock(){
 if(s.riichi)return `<div class="auto-status"><span class="auto-dot"></span> ${autoPaused?'일시정지 · 재개하면 자동으로 이어집니다':'리치 자동 진행 중 · 화료까지 조작할 필요가 없습니다'}</div>`;
 const choices=actionChoices(s,selected,floorSelected),main=choices[0];
 return `<div class="action-dock"><div class="action-caption">${main?.hint||'손패를 선택하세요'}${choices.length>1?'<small>다른 행동은 ▴에서 선택</small>':''}</div><div class="action-control">${actionMenu?`<div class="action-menu" role="menu" aria-label="가능한 행동">${choices.map((x,i)=>`<button role="menuitem" data-choice="${i}"><strong>${x.label}</strong><small>${x.hint}</small></button>`).join('')}</div>`:''}<button class="primary main-action" data-choice="0" ${!main?'disabled':''}>${main?.label||'패 선택'}</button>${choices.length>1?`<button class="action-toggle" data-actions="1" aria-label="다른 행동 선택" aria-expanded="${actionMenu}">▴</button>`:''}</div></div>`;
}
function handRack(){const view=handView(s);return `<div class="hand hand-rack" style="--hand-columns:${s.hand.length<=8?Math.max(1,s.hand.length):7}" data-hand-drop="1"><div class="hand-main">${view.body.map(x=>tile(x,'hand')).join('')}</div>${view.draw?`<div class="draw-slot"><span class="draw-caption">쯔모</span>${tile(view.draw,'hand')}</div>`:''}</div>`;}
function resultHand(r){if(!r.layout)return `<div class="hand">${r.hand.map(x=>tile(x)).join('')}</div>`;const labels={sequence:'몸통 · 순자',triplet:'몸통 · 각자',kan:'몸통 · 깡',pair:r.layout.kind==='pairs'?'쌍':'머리',orphans:'국사무쌍'};return `<div class="winning-groups" aria-label="화료 패 구성">${r.layout.groups.map(g=>`<div class="winning-group ${g.kind}"><div>${g.tiles.map(x=>tile(x)).join('')}</div><span>${g.open?'공개 ':''}${labels[g.kind]}</span></div>`).join('')}</div><p class="muted">${r.layout.kind==='normal'?'몸통을 먼저, 머리를 마지막에 모았습니다.':'특수 완성형으로 묶었습니다.'}${r.shapes.length>1?' 표시는 대표 완성형이며, 성립한 다른 역도 점수에 포함됩니다.':''}${r.rig?' 조작패는 이 완성형에서 사용한 속성으로 표시됩니다.':''}</p>`;}
function waitPanel(riichi){
 const types=riichi?.waits||(s.riichi?waits(s.phase==='action'?s.hand.filter(t=>t.id!==s.drawn):s.hand,meldCount(s),s.locked):[]);
 if(!types.length)return '';
 const rows=remainingWaits(s,types),total=rows.reduce((n,x)=>n+x.remaining,0);
 return `<div class="wait-estimate" aria-label="리치 대기패 추정"><strong>${s.riichi?'리치 중 ·':'선택한 패를 버리면'} 대기패 ${types.length}종 · 미확인 ${total}장</strong><div class="wait-counts">${rows.map(x=>`<span class="${x.remaining?'':'exhausted'}">${tileName(x.type)} <b>${x.remaining}장</b>${x.remaining?'':' · 모두 확인됨'}</span>`).join('')}</div><p>비공개 제외패·뒷도라도 포함한 수입니다. 실제로 뽑을 수 있는 패는 더 적을 수 있습니다.</p><details><summary>계산 방법과 주의점</summary><p>각 종류 4장에서 손패·바닥패·고정 몸통·버림패·공개 표시패를 뺀 수입니다. 비공개 제외패와 미공개 뒷도라도 포함하므로, 실제로 뽑을 수 있는 장수는 더 적을 수 있습니다. 조작한 패는 원래 종류로 차감합니다. 리치 후에는 쯔모로만 화료합니다.</p></details></div>`;
}
function board(){
 const ops=options(),riichi=ops.riichi.find(x=>x.id===selected);
 const intro=s.phase==='awaitDraw'?'손패를 받았습니다. 쯔모를 눌러 첫 패를 뽑으세요.':s.riichi?'자동 쯔모·쯔모기리 중 · 바닥패 잠김':s.phase==='action'?`몸통 ${meldCount(s)}개와 머리 1개. 패를 고르면 가능한 행동이 손패 아래에 표시됩니다.`:s.phase==='callDiscard'?'몸통은 고정되었습니다. 1장을 버리면 다음 쯔모를 받습니다.':'기본은 넘기기입니다. 바닥패를 직접 선택하면 론·울기를 고를 수 있습니다.';
 return `<section class="table"><div class="table-head"><div><h2>${s.handNo}번째 손</h2><span class="muted">목표 · 몸통 ${meldCount(s)}개 + 머리 1개 (${3*meldCount(s)+2}장)</span></div><div class="row"><span class="badge ${s.locked.some(x=>x.open&&!x.stealth)?'open':''}">${s.locked.some(x=>x.open&&!x.stealth)?'멘젠 해제':'멘젠'}</span>${s.riichi?`<span class="riichi-stick" aria-label="리치 선언"></span><span class="muted">${s.riichiDraws<=4?`일발 기회 · 쯔모 ${s.riichiDraws}/4`:'일발 종료'}</span>`:''}</div></div>${s.riichi?chasePanel():''}${recipePanel()}${floorPanel()}${s.locked.length?`<div class="locked">${s.locked.map(g=>`<div class="meld ${g.open?'':'closed'}">${g.tiles.map(x=>tile(x)).join('')}<span class="meld-label">${g.stealth?'은밀 · 멘젠 유지 · ':''}${g.kind==='kan'?(g.open?'공개깡':'암깡'):g.kind==='sequence'?'치':'퐁'}</span></div>`).join('')}</div>`:''}<div class="hand-area"><div class="hand-heading"><h3>손패 ${s.hand.length}장 <span class="muted">${s.riichi?'· 리치 중 고정':s.autoSortHand?'· 종류·숫자순 자동 정렬':'· 드래그로 순서 변경'}</span></h3><button class="sort-toggle ${s.autoSortHand?'active':''}" data-auto-sort="1" role="switch" aria-checked="${s.autoSortHand}" aria-label="손패 자동 정렬">자동 정렬 ${s.autoSortHand?'ON':'OFF'}</button><button class="quiet sort-hand" data-sort-hand="1" ${s.riichi||s.autoSortHand?'disabled':''}>한 번 정렬</button></div>${handRack()}</div>${waitPanel(riichi)}<div class="board-bottom"><p class="instructions">${intro}</p>${actionDock()}</div></section>`;
}
function resultPanel(){const r=s.lastResult;return `<section class="table pulse"><span class="badge">${s.score>=s.target?'라운드 목표 달성':'화료 성공 · 패산은 이어집니다'}</span><div class="result-title">${r.source==='ron'?'론':'쯔모'}${r.yaku.some(x=>x.name.startsWith('일발'))?' · 일발':''}</div><div class="result-score">${r.score.toLocaleString()} <small>점</small></div><p>${r.base} 기본점 × ${r.mult} 배율</p>${resultHand(r)}<div class="result-yaku">${r.yaku.map(y=>`<div><span>${y.name}</span><span>+${y.weight}</span></div>`).join('')}<div><span>도라 / 뒷도라 / 적도라</span><span>+${r.dora} / +${r.ura} / +${r.red}</span></div><div><span>직접 조작 보너스</span><span>+${r.manual||0}</span></div></div>${r.chase?chasePanel(r.chase,true):''}${r.effects.map(t=>`<p class="muted">${t}</p>`).join('')}<p class="muted">${r.shapes.join(' + ')} · 손패·몸통·바닥패를 모두 소비했습니다. 다음 손에 바닥패와 도안을 새로 배치합니다.</p><div class="actions" style="margin-top:20px"><button class="primary" data-act="continue">${s.score>=s.target?(s.chapter===CHAPTERS&&s.isBoss?'도전 결과 보기':'보상 받고 상점으로'):'같은 패산에서 다음 손 받기'}</button></div></section>`;}
function nextInfo(){let c=s.chapter,r=s.round+1;if(r>2){c++;r=1;}const b=r===2?bossFor(s,c):null;return `${c}챕터 ${r}라운드 · 몸통 ${c+1} + 머리 · 목표 ${roundTarget(c,r,b)}점${b?` · 보스 ${b.name}: ${b.text}`:''}`;}
function productCard(id,mode='buy'){
 const x=itemById(id),isPack=x.kind==='pack',cost=price(s,x),owned=x.kind==='recipe'?`보유 ${s.recipes[id]||0}장 · +1장`:s.tools[id]?`보관 ${s.tools[id].left}개`:'',disabled=!eligible(s,x)||(mode!=='pickPack'&&s.coins<cost);
 const symbol={recipe:'紋',gear:'符',consumable:'術',pack:'包'}[x.kind];
 return `<article class="product-card kind-${x.kind}"><div class="product-art"><span>${symbol}</span><small>${KIND_NAMES[x.kind]}</small></div><div class="product-copy"><span class="product-type">${KIND_NAMES[x.kind]} ${owned}</span><h3>${x.name}</h3><p>${x.text}</p></div><button data-${isPack?'open-pack':mode==='pickPack'?'pick-pack':'buy'}="${id}" ${disabled?'disabled':''}>${mode==='pickPack'?'선택 · 추가 비용 없음':`${cost}냥 · ${isPack?'열기':'구매'}`}</button></article>`;
}
function focusPrompt(){return s.equipment.includes('focus')&&!s.focus?.target?`<section class="panel focus-prompt"><h3>한 우물 · 목표 역을 선택하세요</h3><p>해당 역 화료 시 기본점 +20. 성공마다 다음 보너스 +10. 선택 후 판매 전까지 고정됩니다.</p><div class="actions">${FOCUS_YAKU.map(target=>`<button data-focus="${target}">${target}</button>`).join('')}</div></section>`:'';}
function shop(){
 if(s.pendingPack)return `<section class="table"><span class="muted">구매 완료 · 추가 비용 없음</span><h2>${itemById(s.pendingPack.id).name}</h2><p>공개된 ${s.pendingPack.choices.length}개 중 1개를 선택하세요.</p><div class="pack-choices">${s.pendingPack.choices.map(id=>productCard(id,'pickPack')).join('')}</div><button data-act="skipPack">선택 포기 · 환불 없음</button></section>`;
 return `${focusPrompt()}<section class="table shop-table"><div class="row spread"><div><span class="muted">라운드 보상 +${s.reward}냥</span><h2>작탁 사이의 정비</h2></div><span class="score-total">${s.coins}냥</span></div><p class="price-mode">도안은 개당 1냥입니다. 사면 다른 상품이 바로 들어오며, 같은 도안도 여러 장 살 수 있습니다.</p><p class="muted">${s.config.priceMode==='feel'?'효과 체험: 다른 상품·팩·재진열도 1냥, 장비 판매 0냥':'장비·소모품은 표시된 가격으로 구매'} · 다음: ${nextInfo()}</p>${recipePanel()}<details class="recipe-guide"><summary>도안은 언제, 어떻게 쓰나요?</summary><p>도안은 한 번 쓰고 없어지는 아이템이 아닙니다. 구매한 뒤 새 손을 받을 때마다 바닥패에 자동으로 효과를 붙입니다. 패를 누르면 붙은 효과와 사용 방법을 읽을 수 있습니다.</p><p>같은 도안을 여러 장 사면 여러 패에 나누어 붙습니다. 한 패에 같은 도안이 반복해서 붙어도 효과는 한 번만 적용됩니다. 조건에 맞는 패가 없으면 이번 배치에서는 쉬고, 다음 배치에서 다시 시도합니다.</p><p>숫자·종류를 바꾸는 도안은 한 패에 하나만 붙습니다. 소매·은밀·보충은 그 위에 함께 붙을 수 있습니다. 도안 자체로 점수를 주지는 않지만, 새로운 조합을 만들어 더 좋은 역을 노릴 수 있습니다.</p></details><div class="shelf-label"><h3>바닥패 도안 · 무한 입고</h3><small>새 손이 시작될 때, 산 도안마다 조건에 맞는 바닥패 한 장을 무작위로 골라 효과를 붙입니다.</small></div><div class="recipe-shop">${s.recipeOffers.map(id=>productCard(id)).join('')}</div><div class="shelf-label"><h3>장비·소모품</h3><button data-act="reroll" ${s.coins<rerollCost(s)?'disabled':''}>${rerollCost(s)}냥 · 재진열</button></div><div class="recipe-shop">${s.offers.map(id=>productCard(id)).join('')||'<p class="empty-shelf">재진열로 새 상품 보기</p>'}</div><div class="shelf-label"><h3>선택 팩</h3><small>재진열해도 도안·팩은 유지</small></div><div class="pack-shelf">${s.packOffers.map(id=>productCard(id)).join('')}</div><div class="actions"><button class="primary" data-act="nextRound" ${s.equipment.includes('focus')&&!s.focus?.target?'disabled':''}>다음 라운드 시작</button><button data-modal="catalog">전체 상품 목록</button></div><details class="sell-list"><summary>장비 정리 · ${s.equipment.length}/5칸 (각 ${sellValue(s)}냥)</summary><div class="actions">${s.equipment.map(id=>`<button data-sell="${id}">${itemById(id).name} 판매</button>`).join('')||'<span>보유 장비 없음</span>'}</div></details></section>`;
}
function end(){return `<section class="table"><span class="muted">${s.practice?'연습 종료':'도전 결과'}</span><h2 class="result-title">${s.phase==='won'?'마지막 작탁을 넘었습니다':'패산이 다했습니다'}</h2><p>${esc(s.reason||'3챕터의 모든 라운드를 통과했습니다.')}</p><div class="result-yaku"><div><span>도달</span><span>${s.chapter}챕터 ${s.round}라운드</span></div><div><span>화료</span><span>${s.stats.wins}회</span></div><div><span>최고 한 손</span><span>${s.stats.best.toLocaleString()}점</span></div><div><span>부족한 점수</span><span>${Math.max(0,s.target-s.score)}</span></div></div><details><summary>이번 라운드에서 비공개 제외했던 ${s.excluded.length}장</summary><div class="hand">${s.excluded.map(x=>tile(x)).join('')}</div></details><div class="actions" style="margin-top:20px"><button class="primary" data-retry="same">같은 시드로 다시</button><button data-modal="settings">새 도전 설정</button><button data-export="1">테스트 기록 저장</button></div></section>`;}
function render(){
 s.autoSortHand=autoSortHand;chooseDefaults();const ops=options();const preview=['result','shop','won'].includes(s.phase)?s.lastResult:s.phase==='floor'?ops.ron.find(x=>x.tile.id===floorSelected)?.score:ops.tsumo;
 app.innerHTML=`<div class="shell"><header class="header"><div class="brand"><span class="brand-mark">發</span><div><span class="muted">혼자 두는 마작 · PROTOTYPE V2.8</span><h1>밤의 작탁</h1></div></div><nav class="nav">${s.practice?'<button data-back-run="1">도전으로 돌아가기</button>':''}<button data-modal="help">게임 방법</button><button data-modal="practice">규칙 연습</button><button data-modal="catalog">상품 목록</button><button data-sound="1">효과음 ${sound?'켜짐':'꺼짐'}</button><button data-export="1">기록 저장</button><button data-modal="settings">새 도전</button></nav></header><div class="journey"><div><strong>${s.practice?'연습 · ':''}${s.chapter}챕터 / 3 · ${s.round}라운드 / ${s.config.roundsPerChapter}</strong><div class="muted">${s.isBoss?'보스 라운드':'일반 라운드'} · 몸통 ${meldCount(s)}개 + 머리 1개</div></div><div class="chapter-path">${[1,2,3].map(c=>`<span class="chapter-dot ${c===s.chapter?'current':c<s.chapter?'done':''}">${c}</span>`).join('')}</div></div><div class="layout"><aside class="stack sidebar"><section class="panel"><span class="muted">라운드 점수</span><div class="score-total">${s.score.toLocaleString()}</div><div class="goal">${s.practice?'연습 · 목표 없음':`목표 ${s.target.toLocaleString()}점`}</div><div class="track"><div style="width:${Math.min(100,s.score/s.target*100)}%"></div></div><span class="muted">${['result','shop','won'].includes(s.phase)?'지난 화료':'선택한 화료 미리보기'}</span><div class="scoreboxes"><div class="scorebox base"><span>기본점</span><div class="score-number">${preview?.valid?preview.base:'—'}</div></div><div class="scorebox mult"><span>배율</span><div class="score-number">${preview?.valid?'×'+preview.mult:'—'}</div></div></div><div class="score-total" style="font-size:${preview?.valid?25:16}px;margin-top:12px">${preview?.valid?preview.score.toLocaleString()+'점':'완성형을 만드세요'}</div>${s.riichi&&(s.uraKnown||0)<s.ura.length?'<p class="muted">비공개 뒷도라 보너스는 화료 때 추가됩니다.</p>':''}<div class="chips">${preview?.yaku?.map(x=>`<span class="chip">${x.name} +${x.weight}</span>`).join('')||''}</div></section><section class="panel"><h3>남은 패산</h3><div class="score-total">${s.wall.length}<small>장</small></div><span class="muted">비공개 제외 ${s.excluded.length}장 · 재투입 없음</span><div class="stats"><div class="stat"><span class="muted">쯔모</span><strong>${s.turn}</strong></div><div class="stat"><span class="muted">소지금</span><strong>${s.coins}</strong></div></div></section></aside><main class="stack">${s.boss?`<div class="boss"><strong>${s.boss.name}</strong> · ${s.boss.text}</div>`:''}<div class="topline">${gearPanel()}${doraPanel()}</div>${['action','floor','callDiscard','awaitDraw'].includes(s.phase)?board():s.phase==='result'?resultPanel():s.phase==='shop'?shop():end()}${!['failed','won'].includes(s.phase)?toolPanel():''}<div class="panel"><details><summary>버려진 패 ${s.discards.length}장 · 최근 진행</summary><div class="discards" style="margin-top:12px">${s.discards.map(x=>`<span>${tileName(x.type)}</span>`).join('')}</div><div class="log">${s.log.slice(-18).reverse().map(x=>`<div>${x.turn}순 · ${esc(x.message)}</div>`).join('')}</div></details></div></main></div><footer class="footer"><span>시드 ${esc(s.seed)} · ${s.practice?'연습은 저장되지 않음':'진행은 이 브라우저에 자동 저장'} · 정통 리치마작과 다른 실험 규칙</span><div>${esc(s.message)}</div></footer></div>`;
 scheduleAuto();
}
function scheduleAuto(){
 clearTimeout(autoTimer);autoTimer=null;
 if(!s.riichi||autoPaused||document.querySelector('dialog[open]'))return;
 const next=riichiAction(s);if(!next)return;
 autoTimer=setTimeout(()=>{autoTimer=null;const current=riichiAction(s);if(current&&!autoPaused&&!document.querySelector('dialog[open]'))dispatch(current.action,current.payload||{});},riichiDelay(s));
}
function dispatch(action,payload={}){try{clearTimeout(autoTimer);const next=structuredClone(s);act(next,action,payload);assertState(next);if(next.phase==='floor'&&s.phase!=='floor')floorSelected=null;if(next.drawn!==s.drawn&&next.hand.some(t=>t.id===next.drawn))selected=next.drawn;s=next;if(action==='sleeve')selected=payload.take;cached=null;actionMenu=false;if(action==='riichi')autoPaused=false;chooseDefaults();save();render();beep(['tsumo','ron'].includes(action)?'win':action==='riichi'?'riichi':'click');}catch(e){autoPaused=true;toast(e.message);}}
let draggingHand=null,suppressHandClickUntil=0;
function clearDropHint(){document.querySelectorAll('.drop-before,.drop-after,.drag-source').forEach(x=>x.classList.remove('drop-before','drop-after','drag-source'));}
document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-hand]');if(!b||s.riichi||s.autoSortHand){e.preventDefault();return;}draggingHand=b.dataset.hand;e.dataTransfer.setData('text/plain',draggingHand);e.dataTransfer.effectAllowed='move';b.classList.add('drag-source');});
document.addEventListener('dragover',e=>{if(!draggingHand||!e.target.closest('[data-hand-drop]'))return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-before','drop-after'));const b=e.target.closest('[data-hand]');if(b&&b.dataset.hand!==draggingHand){const r=b.getBoundingClientRect();b.classList.add(e.clientX>r.left+r.width/2?'drop-after':'drop-before');}});
document.addEventListener('drop',e=>{if(!draggingHand)return;const id=draggingHand;draggingHand=null;clearDropHint();if(!e.target.closest('[data-hand-drop]'))return;e.preventDefault();const b=e.target.closest('[data-hand]');const after=b?e.clientX>b.getBoundingClientRect().left+b.getBoundingClientRect().width/2:false;if(moveHandTile(s,id,b?.dataset.hand||null,after)){selected=id;suppressHandClickUntil=Date.now()+300;save();render();}});
document.addEventListener('dragend',()=>{draggingHand=null;suppressHandClickUntil=Date.now()+300;clearDropHint();});
document.addEventListener('keydown',e=>{const b=e.target.closest('[data-hand]');if(!b||!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const order=syncHandOrder(s),i=order.indexOf(b.dataset.hand),right=e.key==='ArrowRight',target=order[i+(right?1:-1)];if(target&&moveHandTile(s,b.dataset.hand,target,right)){selected=b.dataset.hand;save();render();document.querySelector(`[data-hand="${CSS.escape(selected)}"]`)?.focus();}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.hand&&Date.now()<suppressHandClickUntil)return;
 if(b.dataset.autoSort){autoSortHand=!autoSortHand;setHandAutoSort(s,autoSortHand);try{localStorage.setItem(SORT_KEY,autoSortHand?'on':'off');}catch{}save();render();return;}
 if(b.dataset.sortHand){sortHand(s);save();render();return;}
 if(b.dataset.close){document.getElementById(b.dataset.close).close();scheduleAuto();return;}
 if(b.dataset.modal){clearTimeout(autoTimer);document.getElementById(b.dataset.modal).showModal();return;}
 if(b.dataset.pause){autoPaused=!autoPaused;render();return;}
 if(b.dataset.actions){actionMenu=!actionMenu;render();return;}
 if(b.dataset.choice!==undefined){const choice=actionChoices(s,selected,floorSelected)[Number(b.dataset.choice)];if(choice)dispatch(choice.action,choice.payload);return;}
 if(b.dataset.focus){dispatch('chooseFocus',{target:b.dataset.focus});return;}
 if(b.dataset.openPack){dispatch('openPack',{id:b.dataset.openPack});return;}
 if(b.dataset.pickPack){dispatch('pickPack',{id:b.dataset.pickPack});return;}
 if(b.dataset.hand){if(s.riichi)return;actionMenu=false;selected=b.dataset.hand;render();return;}if(b.dataset.floor){actionMenu=false;floorSelected=floorSelected===b.dataset.floor?null:b.dataset.floor;render();return;}
 if(b.dataset.toolUse){dispatch('tool',{tool:selectedTool,id:b.dataset.toolUse==='floor'?floorSelected:selected,area:b.dataset.toolUse});return;}
 if(b.dataset.tool){selectedTool=b.dataset.tool;render();return;}
 if(b.dataset.sound){sound=!sound;render();beep('click');return;}
 if(b.dataset.act){dispatch(b.dataset.act,{id:b.dataset.act==='ron'?floorSelected:selected,tool:selectedTool});return;}
 if(b.dataset.call!==undefined){dispatch('call',options().calls[Number(b.dataset.call)]);return;}
 if(b.dataset.kan!==undefined){dispatch('kan',options().kans[Number(b.dataset.kan)]);return;}
 if(b.dataset.buy){dispatch('buy',{id:b.dataset.buy});return;}
 if(b.dataset.sell){dispatch('sell',{id:b.dataset.sell});return;}
 if(b.dataset.practice){if(!s.practice)campaign=structuredClone(s);s=practice(b.dataset.practice,{priceMode:s.config.priceMode});cached=null;selected=null;floorSelected=null;autoPaused=false;actionMenu=false;document.getElementById('practice').close();render();return;}
 if(b.dataset.backRun){s=campaign||newGame();campaign=null;autoPaused=false;actionMenu=false;cached=null;selected=null;floorSelected=null;save();render();return;}
 if(b.dataset.retry){s=newGame({...s.config,seed:s.seed});autoPaused=false;actionMenu=false;cached=null;selected=null;floorSelected=null;save();render();return;}
 if(b.dataset.export){const data={version:27,seed:s.seed,config:s.config,practice:s.practice||null,phase:s.phase,chapter:s.chapter,round:s.round,bossOrder:s.bossOrder||[1,2,3].map(c=>bossFor(s,c).id),target:s.target,boss:s.boss?.id||null,stats:s.stats,recipes:s.recipes,equipment:s.equipment,tools:s.tools,moneyHistory:s.moneyHistory||[],riichiChase:s.lastResult?.chase||s.riichiRun,records:s.records,log:s.log};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`night-table-v2-${s.seed.replace(/[^a-zA-Z0-9_-]/g,'_')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.getElementById('new-run-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);s=newGame({seed:String(f.get('seed')).trim()||crypto.randomUUID().slice(0,8),excluded:Number(f.get('excluded')),roundsPerChapter:Number(f.get('rounds')),red:f.has('red'),priceMode:String(f.get('priceMode'))});cached=null;selected=null;floorSelected=null;campaign=null;autoPaused=false;actionMenu=false;save();document.getElementById('settings').close();render();});
document.getElementById('help-content').innerHTML=`<p><strong>3챕터의 보스를 모두 넘기면 승리합니다.</strong> 각 라운드에서 패산이 소진되기 전에 목표 점수를 모으세요. 화료 횟수는 제한이 없습니다.</p><h3>6라운드와 보스</h3><p>챕터마다 일반 1회 + 보스 1회입니다. 세 보스는 도전마다 순서를 섞어 한 번씩 등장합니다. 보스 직전 상점에서 다음 기믹과 목표를 확인할 수 있습니다.</p><p>v2.8 체험용 임시 목표: ${ROUND_TARGETS.map((v,i)=>`${i+1}챕터 ${v[0]} → ${v[1]}점`).join(' / ')}. 무거운 작탁은 기본점을 20% 줄이는 대신 목표를 10% 낮춰 적용합니다.</p><h3>손패 정렬</h3><p>자동 정렬 ON이면 손패 변경 때마다 종류·숫자순으로 정렬합니다. OFF이면 손패를 드래그해 정한 배치를 유지합니다. 토글 설정은 새 도전과 새로고침 후에도 유지됩니다. 키보드는 패에 초점을 둔 뒤 Alt+←/→. 한 번 정렬 버튼은 자동 정렬을 켜지 않고 현재 손패만 정렬합니다. 쯔모패는 오른쪽에 따로 표시되며, 버린 뒤에는 손패로 합쳐집니다. 쯔모패를 직접 드래그해서 먼저 합칠 수도 있습니다.</p><h3>한 손의 흐름</h3><ol><li>챕터당 몸통 2→3→4개와 머리 1개를 만듭니다. 일반 완성형은 8→11→14장입니다.</li><li>쯔모 후 화료하거나 1장을 버립니다. 바닥패는 배패 때 5장 공개되어 계속 유지됩니다.</li><li>론·치·퐁·대명깡을 고를 수 있습니다. 치·퐁 뒤에도 1장을 버리고 다음 쯔모를 받습니다.</li><li>바닥패를 지나가도 버리지 않습니다. 가져간 자리는 비워 두고, 화료할 때만 전체를 교체합니다. 후리텐은 없습니다.</li><li>화료한 패와 몸통·바닥패는 모두 소비합니다. 같은 패산에서 새 배패를 받습니다.</li></ol><h3>리치와 깡</h3><p>멘젠 텐파이가 되는 버림패를 선택하면 리치를 선언할 수 있습니다. 이후 쯔모·쯔모기리·쯔모 화료까지 자동으로 진행합니다. 공개 간격은 1.05초에서 시작해 빗나간 쯔모마다 빨라지며 최소 0.18초입니다. 일시정지하거나 안내창을 열면 멈춥니다. 리치 후에는 이미 공개된 바닥패로 론·울기할 수 없습니다. 일반 쯔모 4장 이내 화료는 일발입니다. v2에서는 리치 후 깡·조작을 막습니다.</p><p>대명깡·암깡·가깡을 지원합니다. 암깡은 멘젠을 유지합니다. 깡마다 같은 패산에서 도라·뒷도라 표시패 각 1장과 보충패 1장을 가져옵니다. 최대 4회이며 패산이 3장 미만이면 깡을 할 수 없습니다. 왕패 14장은 별도로 두지 않습니다.</p><h3>도안과 장비</h3><p>도안은 처음에 0장. 상점에서 항상 1냥에 구매하며, 구매 즉시 새 도안이 입고됩니다. 보유·중복 수 제한 없이 모든 도안이 새 바닥패에 각각 발동합니다. 한 패에는 종류 변경 도안 1종과 소매·은밀·보충 도안을 함께 붙일 수 있습니다. 중복 도안은 다른 패에 우선 분산하고, 같은 패의 같은 효과를 더 늘리지는 않습니다. 삼원 도안은 백·발·중 패에만 적용됩니다. 소매는 리치 전 바닥 단계에서 선택 손패와 교환합니다. 은밀은 치·퐁의 멘젠 판정만 유지하며 암각으로 세지 않습니다. 보충은 울기로 가져간 빈칸에 일반패를 채우며 패산을 소모합니다. 대상이 없는 도안은 그 배치에서만 쉽니다. 도안 자체 기본점·배율 보너스는 없습니다. 바뀐 속성으로 만든 역과 도라가 점수에 반영됩니다.</p><p>규칙 강화와 득점 강화는 장비 5칸을 공유합니다. 한 우물은 획득 후 상점에서 목표 역을 선택합니다. 그 역을 성공할 때마다 다음 화료 보너스가 +10 성장합니다. 이전 버전에서 보유한 상품은 유지되지만 신규 진열·팩에서는 나오지 않습니다. 소모품은 기본 2개를 보관하며 손패 또는 바닥패를 골라 사용합니다.</p><h3>점수</h3><p>기본점 = 30 + 몸통 수 × 20 (70 / 90 / 110). 배율 = 1 + 각 역의 가중치 + 도라·뒷도라·적도라 + 직접 조작 보너스. 그 뒤 장비·보스 효과를 적용합니다. 속성 도안에는 별도의 점수 보너스가 없습니다. 올바른 완성형이면 역이 없어도 점수를 줍니다.</p><p>가능한 각 해석에서 성립한 역을 모두 합칩니다. 같은 이름은 한 번만 적용하고, 서로 다른 상·하위 역은 함께 계산합니다. 조작된 패는 한 해석 안에서 한 장으로만 사용합니다. 고정 몸통은 재분해하지 않습니다.</p><h3>라운드에 남는 것</h3><p>도라·뒷도라와 공개된 뒷도라 정보는 유지합니다. 뒷도라 점수는 리치 화료에만 적용합니다. 소모품은 사용하면 사라지고 재충전되지 않습니다. 도안과 장비는 이번 도전 동안 유지됩니다. 비공개 제외패는 라운드 시작 때 무작위로 빼며, 종료 시 확인할 수 있습니다.</p><h3>지원 역 / 실험 정의</h3>${YAKU_HELP.map(([n,t])=>`<p><strong>${n}</strong><br>${t}</p>`).join('')}<p class="muted">추가 지원: 삼색동각, 삼암각·사암각, 찬타·준찬타, 혼노두, 소삼원·대삼원, 소사희·대사희, 자일색·청노두·녹일색, 삼깡자·사깡자, 영상개화. 핑후·구련보등·국사 특수 대기·부수 등은 v2 범위에서 제외합니다.</p>`;
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',scheduleAuto));
